  "verbityypit": {
    "titleEn": "Verb Types 1-6 (Verbityypit)",
    "summaryEn": "Classification of all Finnish verbs into 6 types based on their infinitive endings and stem rules.",
    "overviewEn": "Finnish verbs fall into 6 distinct groups depending on their dictionary infinitive endings.\nMastering the 6 verb types allows you to conjugate any verb in all tenses, moods, and persons.",
    "rulesEn": [
      {
        "title": "Type 1: -V + a/ä (puhua, asua, tietää)",
        "description": "Drop -a/-ä and add personal endings (-n, -t, -e-, etc.). Strong ➔ Weak gradation."
      },
      {
        "title": "Type 2: -da / -dä (syödä, juoda, voida)",
        "description": "Drop -da/-dä; no consonant gradation in the present tense."
      },
      {
        "title": "Type 3: -la/-lä, -na/-nä, -ra/-rä, -sta/-stä (tulla, mennä, purra, pestä)",
        "description": "Insert connective vowel -e- into the present stem (tulla ➔ tulen)."
      },
      {
        "title": "Type 4: -ata / -ätä, -ota / -ötä (haluta, tavata)",
        "description": "Undergoes reverse gradation (tavata ➔ tapaan). Present stem ends in -a/-ä."
      },
      {
        "title": "Type 5: -ita / -itä (tarvita, valita)",
        "description": "Insert -tse- into the present stem (tarvita ➔ tarvitsen)."
      },
      {
        "title": "Type 6: -eta / -etä (lämmetä, paeta)",
        "description": "Insert -ne- into the present stem (lämmetä ➔ lämpenen)."
      }
    ],
    "tableEn": {
      "headers": [
        "Type",
        "Infinitive Ending",
        "Stem Pattern",
        "1st Person Present",
        "English"
      ],
      "rows": [
        [
          "Type 1",
          "-a / -ä",
          "Remove -a/-ä",
          "puhun (puhua)",
          "I speak"
        ],
        [
          "Type 2",
          "-da / -dä",
          "Remove -da/-dä",
          "syön (syödä)",
          "I eat"
        ],
        [
          "Type 3",
          "-la/-na/-ra/-sta",
          "Remove ending + -e-",
          "tulen (tulla)",
          "I come"
        ],
        [
          "Type 4",
          "-ata / -ätä",
          "Remove -t + lengthen vowel",
          "haluan (haluta)",
          "I want"
        ],
        [
          "Type 5",
          "-ita / -itä",
          "Remove -ta + -tse-",
          "tarvitsen (tarvita)",
          "I need"
        ],
        [
          "Type 6",
          "-eta / -etä",
          "Remove -ta + -ne-",
          "lämpenen (lämmetä)",
          "I warm up"
        ]
      ]
    },
    "pitfallsEn": [
      {
        "title": "Type 4 has Reverse Gradation",
        "explanation": "Type 4 verbs start weak in the infinitive (tavata) and strengthen in the present tense (tapaan)."
      }
    ],
    "practiceQuiz": [
      {
        "questionEn": "Which verb type does \"puhua (to speak)\" belong to?",
        "explanationEn": "puhua ends in a vowel + a, making it Verb Type 1."
      },
      {
        "questionEn": "What is the 1st person singular \"minä\" form of \"tulla (to come)\"?",
        "explanationEn": "tulla is Type 3, inserting -e-: tulen."
      },
      {
        "questionEn": "Enter the 1st person form of \"syödä (to eat)\" (minä _____).",
        "hintEn": "sy_____",
        "explanationEn": "Type 2 drops -dä and adds -n: syön."
      },
      {
        "questionEn": "Enter the 1st person form of \"haluta (to want)\" (minä _____).",
        "hintEn": "halu_____",
        "explanationEn": "Type 4 drops -t and adds -an: haluan."
      },
      {
        "questionEn": "Conjugate \"tarvita (to need)\" for \"minä\".",
        "explanationEn": "Type 5 inserts -tse-: tarvitsen."
      }
    ]
  },
